for cls in (Matrix, ImmutableMatrix, SparseMatrix, ImmutableSparseMatrix):
    assert cls.hstack(*(cls.zeros(0, i) for i in range(4))).shape == (0, 6)
    assert cls.vstack(*(cls.zeros(i, 0) for i in range(4))).shape == (6, 0)
    assert cls.hstack(*(cls.zeros(1, i) for i in range(4))).shape == (1, 6)
    assert cls.vstack(*(cls.zeros(i, 1) for i in range(4))).shape == (6, 1)
    for a in range(4):
        for b in range(4):
            for c in range(4):
                assert cls.zeros(a, b).row_join(cls.zeros(a, c)).shape == (a, b + c)
                assert cls.zeros(b, a).col_join(cls.zeros(c, a)).shape == (b + c, a)
    for op, left, right in [('row_join', cls.zeros(0, 2), cls.zeros(1, 2)),
                            ('col_join', cls.zeros(2, 0), cls.zeros(2, 1))]:
        try:
            getattr(left, op)(right)
        except ShapeError:
            pass
        else:
            raise AssertionError('incompatible shapes were accepted')
print('Empty-dimension stacking and shape validation passed for all four matrix classes.')
